CREATE TRIGGER `review_items_values_insert` BEFORE INSERT ON `review_items` WHEN NEW.source NOT IN ('webhook', 'dlq', 'refresh') OR NEW.provider NOT IN ('razorpay', 'stripe', 'paypal') OR NEW.kind NOT IN ('amount_mismatch', 'currency_mismatch', 'reference_mismatch', 'order_mismatch', 'payment_not_on_link', 'not_captured', 'partial_payment', 'unknown_link', 'document_not_payable', 'advance_blocked', 'refetch_failed', 'dead_letter', 'overpaid', 'proforma_overpaid', 'client_gone', 'unreadable_event', 'not_export_receipt', 'capture_pending', 'capture_denied', 'capture_refused', 'reversed_after_confirm', 'refunded_outside', 'late_capture', 'not_final', 'refund_failed', 'refund_stuck', 'dispute_opened', 'dispute_closed', 'refund_after_failed', 'refund_reversed') OR NEW.status NOT IN ('open', 'resolved') OR (NEW.resolution IS NOT NULL AND NEW.resolution NOT IN ('confirmed', 'advance_issued', 'left_as_credit', 'dismissed')) OR NEW.status IS NOT 'open' OR NEW.resolved_by IS NOT NULL OR NEW.resolved_at IS NOT NULL OR NEW.resolution IS NOT NULL OR NEW.note IS NOT NULL BEGIN SELECT RAISE(ABORT, 'review_items_values_insert: a review item starts open with no decision, of a known source, provider and kind'); END;
