CREATE TRIGGER `review_items_values_update` BEFORE UPDATE OF source, provider, kind, status, resolution ON `review_items` WHEN NEW.source NOT IN ('webhook', 'dlq', 'refresh') OR NEW.provider NOT IN ('razorpay', 'stripe', 'paypal') OR NEW.kind NOT IN ('amount_mismatch', 'currency_mismatch', 'reference_mismatch', 'order_mismatch', 'payment_not_on_link', 'not_captured', 'partial_payment', 'unknown_link', 'document_not_payable', 'advance_blocked', 'refetch_failed', 'dead_letter', 'overpaid', 'proforma_overpaid', 'client_gone', 'unreadable_event', 'not_export_receipt', 'capture_pending', 'capture_denied', 'capture_refused', 'reversed_after_confirm', 'refunded_outside', 'late_capture', 'not_final', 'refund_failed', 'refund_stuck', 'dispute_opened', 'dispute_closed', 'refund_after_failed', 'refund_reversed') OR NEW.status NOT IN ('open', 'resolved') OR (NEW.resolution IS NOT NULL AND NEW.resolution NOT IN ('confirmed', 'advance_issued', 'left_as_credit', 'dismissed')) BEGIN SELECT RAISE(ABORT, 'review_items_values_update: a review item has a known source, provider, kind, status and resolution'); END;
