DROP TRIGGER `payment_refunds_bounds`;
--> statement-breakpoint
CREATE TRIGGER `payment_refunds_bounds` BEFORE INSERT ON `payment_refunds` WHEN NOT EXISTS (SELECT 1 FROM payments bp JOIN clients bk ON bk.id = bp.client_id WHERE bp.id = NEW.payment_id AND bp.client_id = NEW.client_id AND bp.currency = NEW.currency
      AND bk.anonymised_at IS NULL AND ((bp.status = 'confirmed' AND bp.kind = 'payment' AND NEW.document_id IS NULL AND NEW.credit_note_id IS NULL AND NEW.amount_minor <= (bp.amount_minor - (SELECT coalesce(sum(CASE pna.kind WHEN 'allocate' THEN pna.amount_minor ELSE -pna.amount_minor END), 0) FROM payment_allocations pna WHERE pna.payment_id = bp.id) - (SELECT coalesce(sum(prf.amount_minor), 0) FROM payment_refunds prf WHERE prf.payment_id = bp.id AND prf.status <> 'failed'))) OR (bp.status = 'confirmed' AND bp.kind = 'payment' AND NEW.document_id IS NOT NULL
      AND EXISTS (SELECT 1 FROM documents d WHERE d.id = NEW.document_id AND d.client_id = bp.client_id AND d.currency = bp.currency AND d.frozen_at IS NOT NULL AND d.status <> 'void'
        AND d.type IN ('tax_invoice', 'export_invoice', 'debit_note') AND (NEW.amount_minor <= (SELECT coalesce(sum(CASE lpa.kind WHEN 'allocate' THEN lpa.amount_minor ELSE -lpa.amount_minor END), 0) FROM payment_allocations lpa JOIN payments lpp ON lpp.id = lpa.payment_id WHERE lpa.document_id = d.id AND lpp.status = 'confirmed' AND lpp.kind = 'payment') + d.credited_minor + (SELECT coalesce(sum(lta.amount_minor), 0) FROM payment_allocations lta JOIN payments ltp ON ltp.id = lta.payment_id WHERE lta.document_id = d.id AND ltp.status = 'confirmed' AND ltp.kind = 'tds' AND lta.kind = 'allocate') - d.total_minor OR NEW.origin = 'chargeback') AND NEW.amount_minor <= (SELECT coalesce(sum(CASE pna.kind WHEN 'allocate' THEN pna.amount_minor ELSE -pna.amount_minor END), 0) FROM payment_allocations pna WHERE pna.payment_id = bp.id AND pna.document_id = d.id))
      AND (NEW.credit_note_id IS NULL OR EXISTS (SELECT 1 FROM documents cn WHERE cn.id = NEW.credit_note_id AND cn.type = 'credit_note' AND cn.parent_id = NEW.document_id AND cn.frozen_at IS NOT NULL AND cn.issue_date >= bp.received_on AND cn.total_minor >= NEW.amount_minor))) OR (bp.status = 'pending_verification' AND bp.kind = 'payment' AND bp.provider <> 'manual' AND NEW.provider = bp.provider AND NEW.document_id IS NULL
      AND NEW.credit_note_id IS NULL AND NEW.amount_minor = bp.amount_minor AND NOT EXISTS (SELECT 1 FROM payment_refunds bx WHERE bx.payment_id = bp.id AND bx.status <> 'failed')))) BEGIN SELECT RAISE(ABORT, 'payment_refunds_bounds: a refund comes from a payment of a live client in its currency: from credit, at most its free money; from the excess of an invoice, at most that excess and what the payment holds on the invoice, naming only a credit note of that invoice issued since the payment arrived that covers the refund; from a pending gateway payment, its whole amount'); END;
--> statement-breakpoint
DROP TRIGGER `payment_refunds_status_flow`;
--> statement-breakpoint
CREATE TRIGGER `payment_refunds_status_flow` BEFORE UPDATE ON `payment_refunds` WHEN (NEW.status IS NOT OLD.status AND NOT ((OLD.status = 'requested' AND NEW.status IN ('processing', 'succeeded', 'failed')) OR (OLD.status = 'processing' AND NEW.status IN ('succeeded', 'failed')) OR (OLD.status = 'succeeded' AND NEW.status = 'failed' AND OLD.provider <> 'manual' AND OLD.origin <> 'chargeback' AND OLD.provider_refund_id IS NOT NULL
      AND OLD.reversed_at IS NULL AND NEW.reversed_at IS NOT NULL AND NEW.failure_code IS NOT NULL AND NEW.settled_at IS OLD.settled_at AND NEW.settled_on IS OLD.settled_on)))
    OR (NEW.status = 'succeeded' AND (NEW.settled_at IS NULL OR NEW.settled_on IS NULL))
    OR (NEW.status <> 'succeeded' AND NEW.reversed_at IS NULL AND (NEW.settled_at IS NOT NULL OR NEW.settled_on IS NOT NULL))
    OR (NEW.reversed_at IS NOT OLD.reversed_at AND NOT (OLD.status = 'succeeded' AND NEW.status = 'failed' AND OLD.provider <> 'manual' AND OLD.origin <> 'chargeback' AND OLD.provider_refund_id IS NOT NULL
      AND OLD.reversed_at IS NULL AND NEW.reversed_at IS NOT NULL AND NEW.failure_code IS NOT NULL AND NEW.settled_at IS OLD.settled_at AND NEW.settled_on IS OLD.settled_on)) BEGIN SELECT RAISE(ABORT, 'payment_refunds_status_flow: a refund goes requested to processing, succeeded or failed, and processing to succeeded or failed; a succeeded refund has its settled time and day, and no other; a gateway refund that succeeded comes back failed once, with its code and the time, keeping its settled fields'); END;
